// spec: specs/edit-listing-save-changes.md (3.1–3.3) · кейсы: .qa/tests/edit-listing-save-changes/EDIT-SAVE-07.md, EDIT-SAVE-08.md
// Нужно своё объявление: QA_EDIT_LISTING_ID=<id> [QA_EDIT_LISTING_ROLE=user]; без него — skip.
// ПРОД: PATCH business?id=eq.<id> перехватывается и отвечается локально (200 или 500), на сервер не уходит; прочие не-GET — abort.
import { test, expect, Page } from '@playwright/test';
import { EDIT_ID, EDIT_ROLE, SKIP_REASON, LOAD, SAVE, TITLE_PH, interceptEdit, openEdit } from './edit-listing.helpers';

const OK_TEXT = 'השינויים נשמרו בהצלחה';
const ERR_TEXT = 'אירעה שגיאה בשמירת המודעה. הפרטים לא נשמרו, אבל הם עדיין בטופס — נסו שוב.';
const OLD_ERR_FRAGMENT = 'הפרטים שמילאתם נשמרו';

test.use({ storageState: `../auth/${EDIT_ROLE}.json`, serviceWorkers: 'block' });

type ToastBox = { left: number; right: number; vw: number; iconOk: boolean; iconFound: boolean };

/**
 * Геометрия toast с текстом text: карточка = ближайший предок текста с непрозрачным фоном
 * (без опоры на CSS-классы библиотеки); иконка = первый svg/img внутри карточки.
 */
async function toastBox(page: Page, text: string): Promise<ToastBox | null> {
  return page.evaluate((t) => {
    const all = Array.from(document.querySelectorAll('body *')) as HTMLElement[];
    const leaf = all.find((el) => el.childElementCount === 0 && (el.textContent || '').includes(t))
      || all.filter((el) => (el.textContent || '').includes(t)).pop();
    if (!leaf) return null;
    let card: HTMLElement | null = leaf;
    while (card && card !== document.body) {
      const bg = getComputedStyle(card).backgroundColor;
      if (bg && bg !== 'transparent' && !/rgba\(0, 0, 0, 0\)/.test(bg)) break;
      card = card.parentElement;
    }
    if (!card || card === document.body) return null;
    const r = card.getBoundingClientRect();
    const vw = document.documentElement.clientWidth || window.innerWidth;
    const icon = card.querySelector('svg, img') as Element | null;
    let iconOk = false;
    if (icon) {
      const ir = icon.getBoundingClientRect();
      iconOk = ir.width > 0 && ir.left >= r.left - 0.5 && ir.right <= r.right + 0.5 && ir.left >= 0 && ir.right <= vw;
    }
    return { left: r.left, right: r.right, vw, iconOk, iconFound: !!icon };
  }, text);
}

/** Ждём конца анимации: toast целиком в экране, отступы слева/справа равны (±1px), иконка целиком видна. */
async function expectToastInside(page: Page, text: string, label: string) {
  await expect(page.getByText(text).first(), `${label}: toast «${text.slice(0, 30)}…» появился`).toBeVisible(LOAD);
  await expect
    .poll(async () => {
      const b = await toastBox(page, text);
      if (!b) return 'нет карточки toast';
      const lm = Math.round(b.left);
      const rm = Math.round(b.vw - b.right);
      if (b.left < 0 || b.right > b.vw) return `за краем: left=${lm}, right-margin=${rm}, vw=${b.vw}`;
      if (Math.abs(lm - rm) > 1) return `отступы не равны: ${lm}/${rm}`;
      if (b.iconFound && !b.iconOk) return 'иконка обрезана';
      return 'ok';
    }, { message: `${label}: toast целиком в экране, отступы равны, иконка видна («מה רצוי» #3bb8cb)`, timeout: 5_000 })
    .toBe('ok');
}

async function qaTitle(page: Page) {
  const title = page.getByPlaceholder(TITLE_PH);
  const newTitle = `QA-AUTO ${(await title.inputValue()).replace(/^QA-AUTO /, '')}`.slice(0, 90);
  await title.fill(newTitle);
  return { title, newTitle };
}

test.describe('Редактирование объявления — toast сохранения (#3bb8cb, #775eeb)', () => {
  test.skip(!EDIT_ID, SKIP_REASON);

  test('На телефоне toast успеха и ошибки целиком в экране #3bb8cb @android', async ({ page }) => {
    const { passed, state, ctl } = await interceptEdit(page, EDIT_ID);

    // Ошибка (500) — остаёмся в форме, toast ошибки
    await openEdit(page, EDIT_ID, state);
    await qaTitle(page);
    ctl.patchStatus = 500;
    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await expectToastInside(page, ERR_TEXT, 'ошибка');
    await expect(page, 'при ошибке остаёмся в форме').toHaveURL(/\/addbusiness\?id=/);

    // Успех (200) — переход на /mybusinesses, toast успеха
    ctl.patchStatus = 200;
    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await page.waitForURL(/\/mybusinesses/, LOAD);
    await expectToastInside(page, OK_TEXT, 'успех');

    expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
  });

  for (const device of ['@desktop', '@android']) {
    test(`Ошибка сохранения: текст «הפרטים לא נשמרו», форма с правкой, повтор сохраняет #775eeb ${device}`, async ({ page }) => {
      const { patches, passed, state, ctl } = await interceptEdit(page, EDIT_ID);
      await openEdit(page, EDIT_ID, state);
      const { title, newTitle } = await qaTitle(page);

      ctl.patchStatus = 500;
      await page.getByRole('button', { name: SAVE, exact: true }).click();
      // «מה רצוי» #775eeb
      await expect(page.getByText(ERR_TEXT).first(), 'toast ошибки с новым текстом').toBeVisible(LOAD);
      await expect(page.getByText(OLD_ERR_FRAGMENT), 'нет старой фразы «הפרטים שמילאתם נשמרו»').toHaveCount(0);
      await expect(page.getByText(OK_TEXT), 'нет toast успеха').toHaveCount(0);
      await expect(page, 'остаёмся в форме редактирования').toHaveURL(/\/addbusiness\?id=/);
      await expect(title, 'введённая כותרת на месте').toHaveValue(newTitle);
      expect(patches.length, 'PATCH сохранения был отправлен (и получил 500)').toBeGreaterThan(0);

      // «נסו שוב»: без ошибки сохранение проходит
      ctl.patchStatus = 200;
      await page.getByRole('button', { name: SAVE, exact: true }).click();
      await page.waitForURL(/\/mybusinesses/, LOAD);
      await expect(page.getByText(OK_TEXT).first(), 'toast «השינויים נשמרו בהצלחה»').toBeVisible(LOAD);
      expect(Object.values(patches[patches.length - 1].body), 'повторный PATCH содержит правку').toContain(newTitle);

      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }
});
